window.BP_SAFAR_APPLIED = {"version":2,"date":"2026-11-13","disclaimer":"سناریوهای آموزشی فرضی مبتنی بر موضوع و تعارض‌های مستند در منابع پروژه به‌پرور؛ گزارش رویداد واقعی شرکت نیستند.","units":[{"skill":"شروع ارتباط، احترام و روشن‌کردن انتظار","alborz":"تکنیک‌های ۱ و ۳: آغاز حرفه‌ای، معرفی و احترام به نقش مخاطب","behparvar":"گفت‌وگوهای کاری و هماهنگی بین‌واحدی در audience-content.js","outcome":"بدون دفاع یا تحمیل، هدف گفت‌وگو و انتظار کاری را روشن کند و حق سؤال طرف مقابل را حفظ کند.","definition":"شروع حرفه‌ای فقط خوشامدگویی نیست؛ باید جایگاه مخاطب، هدف گفت‌وگو و امکان بیان نگرانی روشن شود.","tools":[["شروع سه‌جزئی","مخاطب و وقت او را به رسمیت بشناس؛ هدف مشترک و خروجی مورد انتظار را در دو جمله بیان کن.","«می‌دونم تحویل امروز فشرده‌ست؛ می‌خوام معیار و موعد رو با هم روشن کنیم.»"],["تصحیح بدون شرمسارسازی","اگر جایگاه یا برداشت فردی اشتباه بیان شد، بدون قضاوت نقش واقعی را محترمانه روشن کن.","«این بخش رو همکار کیفیت بررسی می‌کنه؛ بهتره نظر تخصصی ایشون رو بشنویم.»"],["بازکردن فضای مشارکت","به‌جای فرض رضایت، درباره نگرانی و محدودیت سؤال مشخص بپرس؛ بعد قرار رفتاری را مرور کن.","«کجای درخواست ابهام داره؟ برای اطلاع‌دادن مانع چه روشی بهتره؟»"]],"trap":"ادب ظاهری بدون روشن‌کردن تصمیم و حق پرسش می‌تواند همان رابطه دستوری را بازتولید کند.","transfer":"در درخواست بعدی به واحد دیگر، ابتدا هدف مشترک را بگو، بعد محدودیت او را بپرس.","decisionLens":"تفاوت گزینه‌ها در ترتیب «روشن‌کردن هدف، شنیدن برداشت و توافق اجرایی» است؛ پاسخ سریع لزوماً پاسخ مؤثر نیست.","debrief":["کدام جمله به همکار اجازه بیان نگرانی داد بدون اینکه تعهد کار معلق بماند؟","آیا دو طرف یک رفتار مشخص برای ارتباط بعدی توافق کردند؟"],"sup":{"case":"در شروع شیفت، یک کارشناس تازه‌وارد می‌گوید پیام‌های فوری شما برای تحویل گزارش طوری نوشته شده که فرصت سؤال ندارد. ساعت تحویل به واحد بعدی ثابت است و گزارش هنوز یک ورودی ناقص دارد. شما اختیار تغییر استاندارد گزارش را ندارید، اما می‌توانید شیوه هماهنگی و اعلام مانع را اصلاح کنید.","roles":["سرپرست","کارشناس تازه‌وارد"],"roleBriefs":["باید استاندارد تحویل را حفظ کنید؛ مسئله را به بی‌انگیزگی کارشناس نسبت ندهید.","نگران قضاوت‌شدن هستید؛ یک نمونه پیام فوری و یک محدودیت واقعی در اختیار دارید."],"dialogue":[["کارشناس","وقتی می‌نویسید «تا ده دقیقه دیگه تحویل بده»، انگار جایی برای توضیح مشکل نیست."],["سرپرست","مثالی که می‌گی رو می‌فهمم. کجای پیام باعث شد فکر کنی نباید سؤال بپرسی؟"],["کارشناس","ورودی انبار هنوز نرسیده؛ اگر دیر بگم فکر می‌کنید کم‌کاری کردم."],["سرپرست","موعد گزارش پابرجاست، اما من باید علت فوریت رو بگم؛ تو هم مانع رو همان لحظه اطلاع بده."],["کارشناس","پس اگر داده نرسید، گزارش ناقص رو با مشخص‌کردن بخش باز می‌فرستم؟"],["سرپرست","در چارچوب روش مجاز گزارش، بله؛ بخش باز و مسئول پیگیری را روشن می‌کنیم و ساعت ده مرور می‌کنیم."]]},"mgr":{"case":"مدیر تأمین از پیام مدیر برنامه‌ریزی درباره «الزام اختصاص نفر از فردا» ناراضی است؛ آن را دستور یک‌طرفه تلقی می‌کند. پروژه مشتری اهمیت دارد، ولی هر واحد تعهدهای مصوب دیگری هم دارد. تصمیم درباره جابه‌جایی ظرفیت باید با دو مدیر گرفته شود، نه با فرض اختیار یکی بر دیگری.","roles":["مدیر برنامه‌ریزی","مدیر تأمین"],"roleBriefs":["برای موعد پروژه زیر فشارید ولی اختیار تحمیل منابع واحد دیگر را ندارید.","نگران از دست رفتن کنترل ظرفیت و بی‌اعتبارشدن تعهدهای قبلی هستید."],"dialogue":[["مدیر تأمین","پیامتون طوری بود که انگار نفرات ما از قبل تخصیص داده شده‌اند."],["مدیر برنامه‌ریزی","حق دارم روشن کنم: هدفم نیاز پروژه بود، نه تصمیم به جای شما. کدام بخش پیام این برداشت رو ایجاد کرد؟"],["مدیر تأمین","اینکه نوشته بودید «از شنبه باید حاضر باشند»؛ در حالی که تعهد جاری داریم."],["مدیر برنامه‌ریزی","پس اول نیاز حداقلی پروژه و ظرفیت واقعی شما را کنار هم می‌گذاریم."],["مدیر تأمین","شاید یک نفر نیمه‌وقت ممکن باشه، اگر موعدها روشن بشه."],["مدیر برنامه‌ریزی","دو گزینه را مستند می‌کنیم و تصمیم مشترک را با مسئول و موعد اعلام می‌کنیم."]]}},{"skill":"اداره گفت‌وگوی جمعی و نوبت‌دهی در جلسه","alborz":"تکنیک‌های ۵ و ۱۰: مدیریت نوبت، جمع‌بندی و بدرقه حرفه‌ای","behparvar":"کیس «صدایی که در جلسه خاموش شد»، assets/behparvar-cases-4-6.js","outcome":"مخالفت مستند را در جلسه بشنود، زمان تصمیم را حفظ کند و مسئول پیگیری را روشن سازد.","definition":"Facilitation یعنی نگه‌داشتن هم‌زمان صدای افراد، مرز زمان و کیفیت تصمیم؛ نه صرفاً ساکت‌کردن جلسه.","tools":[["قرارداد بحث","در آغاز، تصمیم مورد انتظار، زمان و معیار ارائه شاهد را روشن کن.","«تا ده دقیقه دیگر درباره برنامه تصمیم می‌گیریم؛ هر نگرانی باید شاهد و اثرش رو بگه.»"],["دفاع از حق بیان","مخالفت را از فرد به داده منتقل کن و اجازه پاسخ متوازن بده.","«قبل از تصمیم، شواهد مخالف ظرفیت رو دو دقیقه می‌شنویم.»"],["جمع‌بندی با مالک","برای تصمیم‌های قطعی و موارد باز، مسئول و زمان پاسخ تعریف کن.","«عدد ظرفیت با برنامه‌ریزی تا ساعت دو بازبینی می‌شه؛ تصمیم موقت همین الآن ثبت می‌شه.»"]],"trap":"نوبت‌دهی بدون محافظت از شواهد مخالف، فقط ظاهر مشارکت می‌سازد.","transfer":"در جلسه بعدی از یک نفر بخواه «چه شاهدی می‌تواند تصمیم ما را تغییر بدهد؟» بپرسد.","decisionLens":"فقط وقت جلسه را حفظ نکن؛ اثر داده مخالف بر تصمیم و مالک پیگیری را هم بسنج.","debrief":["آیا داده مخالف به تصمیم وارد شد یا فقط اجازه صحبت داده شد؟","توافق درباره ابهام باقی‌مانده مسئول و موعد داشت؟"],"sup":{"case":"در جلسه هماهنگی میان سرپرستان تولید، تعمیرات و ارسال، یکی از همکاران می‌گوید ظرفیت تعمیر واقعی با برنامه تحویل همخوانی ندارد. مسئول جلسه پاسخ می‌دهد «الان زمان منفی‌بافی نیست». جلسه فقط هشت دقیقه وقت دارد و تصمیم اشتباه می‌تواند دو واحد را درگیر دوباره‌کاری کند.","roles":["سرپرست اداره‌کننده جلسه","سرپرست تعمیرات"],"roleBriefs":["در فشار زمان هستید؛ نمی‌خواهید هشدار فنی نادیده گرفته شود یا جلسه بی‌نتیجه بماند.","دو مشاهده واقعی دارید؛ نگرانید اگر مخالفت کنید به کم‌کاری متهم شوید."],"dialogue":[["تعمیرات","زمان واقعی راه‌اندازی این تجهیز با عدد برنامه یکی نیست."],["اداره‌کننده جلسه","ممنون که قبل از تصمیم گفتی. لطفاً شاهد اصلی و اثرش روی تحویل رو کوتاه بگو."],["تعمیرات","گزارش شیفت قبلی دو ساعت بیشتر از فرض برنامه نشون می‌ده."],["اداره‌کننده جلسه","پس برنامه قطعی نمی‌کنیم؛ گزینه موقت مجاز چیه تا داده دقیق برسد؟"],["تعمیرات","می‌تونیم فعالیت آماده‌سازی را جلو ببریم، ولی زمان راه‌اندازی باید بررسی بشه."],["اداره‌کننده جلسه","این اقدام با مسئول مشخص ثبت می‌شه؛ تصمیم نهایی بعد از تأیید فنی در موعد اعلامی."]]},"mgr":{"case":"در جلسه مدیران عملیات، فروش و برنامه‌ریزی، یک مدیر می‌گوید داده ظرفیت با تعهد مشتری سازگار نیست؛ مدیر دیگر برای حفظ اعتبار جلسه می‌خواهد اختلاف مطرح نشود. تصمیم بودجه‌ای نزدیک است و تأخیر هم هزینه دارد. جلسه باید داده مخالف را شنیده و بین تصمیم قطعی و مشروط تمایز بگذارد.","roles":["مدیر تسهیل‌گر جلسه","مدیر برنامه‌ریزی"],"roleBriefs":["باید جلسه را جمع کنید، اما نمی‌توانید شاهد مهم را برای آرامش ظاهری کنار بگذارید.","داده مخالف دارید و می‌خواهید آن را بدون تحقیر سایر مدیران مطرح کنید."],"dialogue":[["برنامه‌ریزی","این ظرفیت هنوز با سفارش جدید سازگار نیست؛ دو داده متناقض داریم."],["تسهیل‌گر","قبل از تصمیم، کدام داده بیشترین اثر رو روی ریسک تعهد دارد؟"],["برنامه‌ریزی","زمان آماده‌سازی تأمین؛ رقم جلسه قبلی به‌روز نشده."],["تسهیل‌گر","به جای مناقشه بر سر مقصر، دامنه تصمیمی که به این داده وابسته است رو مشخص کنیم."],["برنامه‌ریزی","می‌شه بخش غیر وابسته رو امروز تصویب کرد و باقی رو بعد از راستی‌آزمایی بست."],["تسهیل‌گر","در صورت مجازبودن تفکیک، همین مسیر را با مالک داده و زمان بازبینی در صورت‌جلسه ثبت می‌کنیم."]]}},{"skill":"شنود فعال، بازتاب و فهم مسئله","alborz":"شنود مؤثر جلسه سوم و تکنیک ۹: شنیدن انتظارهای متفاوت","behparvar":"کیس «اعتراض به انصاف تقسیم شیفت»، assets/behparvar-cases-4-6.js","outcome":"اعتراض کلی را به شاهد مشخص، دغدغه اصلی و معیار قابل بررسی تبدیل کند.","definition":"شنود یعنی پیش از راه‌حل، تفاوت مشاهده، تفسیر، احساس و نیاز را روشن کنی؛ همدلی به‌معنای تأیید ادعا نیست.","tools":[["پرسش مصداقی","به‌جای پرسش «چرا همیشه ناراضی هستی؟»، یک رخداد قابل بررسی بخواه.","«در کدام شیفت یا تصمیم این تفاوت رو دیدی؟»"],["بازتاب دو‌لایه","هم واقعیت نقل‌شده و هم اثر آن بر فرد را بازگو و تأیید کن.","«می‌گی سه شیفت دشوار پشت سر هم داشتی و حس می‌کنی معیار یکسان نبوده؛ درست گرفتم؟»"],["جداسازی انصاف از برابری","پیش از وعده تغییر، معیار مهارت، داده تخصیص و حق بررسی را روشن کن.","«الگوی چند هفته رو بررسی می‌کنیم؛ بعد درباره معیار و فرصت آموزش تصمیم می‌گیریم.»"]],"trap":"وعده تقسیم برابر بدون دیدن الزام مهارتی ممکن است ناعادلانه یا ناایمن باشد.","transfer":"در نخستین اعتراض به انصاف، قبل از دفاع از تصمیم، شاهد و معیار تخصیص را روشن کن.","decisionLens":"بین توجه به احساس فرد، اثبات یا رد ادعا و اقدام با داده واقعی تفاوت بگذار.","debrief":["کدام پرسش یک قضاوت کلی را به شاهد قابل راستی‌آزمایی تبدیل کرد؟","آیا سرپرست از همدلی به معنای موافقت فوری استفاده کرد؟"],"sup":{"case":"سه نفر از کارکنان می‌گویند شیفت‌های سخت به‌طور تکراری به آن‌ها می‌رسد. شما تجربه‌های تخصصی متفاوت افراد را می‌شناسید، ولی جدول چند هفته اخیر را کامل همراه ندارید. یکی از کارکنان می‌ترسد اعتراضش روی ارزیابی اثر بگذارد. نباید بدون بررسی وعده تعویض بدهید.","roles":["سرپرست تقسیم کار","کارمند معترض"],"roleBriefs":["محدودیت مهارت وجود دارد اما داده کامل ندارید؛ بی‌طرفی و حق اعتراض را حفظ کنید.","سه نمونه دارید و احساس می‌کنید صدایتان شنیده نشده؛ از برچسب مشکل‌ساز می‌ترسید."],"dialogue":[["کارمند","انگار شیفت‌های سخت همیشه برای ماست."],["سرپرست","می‌خوام بدون قضاوت بفهمم؛ سه مورد اخیر رو مشخص می‌کنی؟"],["کارمند","سه پنجشنبه پشت سر هم مسئول پاسخ فوری بودم."],["سرپرست","پس هم تکرار وظیفه ناراحتت کرده هم اینکه معیار تقسیم روشن نبوده؛ درست فهمیدم؟"],["کارمند","بله. حتی اگر دلیل فنی داشته، هیچ‌وقت به ما نگفتید."],["سرپرست","معیار و داده رو بررسی می‌کنم و نتیجه رو با دلیل می‌گم؛ درباره امکان یادگیری مهارت‌های لازم هم گفت‌وگو می‌کنیم."]]},"mgr":{"case":"دو مدیر درباره علت تأخیر یک پروژه مشترک گزارش‌های متفاوت دارند؛ یکی «کم‌کاری طرف مقابل» را مطرح می‌کند و دیگری به تغییرهای بدون هماهنگی اشاره می‌کند. گزارش‌های سیستم فقط بخشی از رویدادها را ثبت کرده‌اند. تصمیم‌گیری فوری درباره مسئولیت‌ها بدون فهم داده و برداشت ممکن است تعارض را تشدید کند.","roles":["مدیر راهبر","مدیر واحد"],"roleBriefs":["از تعیین مقصر پیش از شواهد پرهیز کنید؛ اختلاف را به رویداد و وابستگی تبدیل کنید.","از اعتبار تیم خود دفاع می‌کنید؛ نمونه تغییر دامنه و یک خطای داخلی را می‌دانید."],"dialogue":[["مدیر واحد","این تأخیر کاملاً به خاطر واحد دیگر بود."],["مدیر راهبر","چه رخدادی دقیقاً مسیر کار رو تغییر داد؟"],["مدیر واحد","خواسته‌ها دو بار عوض شد و موعد همان قبلی ماند."],["مدیر راهبر","می‌شنوم که درباره اثر تغییر دامنه نگرانید؛ کدام داده نشان می‌ده این تغییر به موعد منتقل نشده؟"],["مدیر واحد","ایمیل اصلاح سفارش هست؛ البته ما هم دیر اطلاع دادیم."],["مدیر راهبر","پس روایت مشترک رو با این دو شاهد می‌سازیم و بعد مسئولیت اصلاح رو مشخص می‌کنیم."]]}},{"skill":"بیان روشن، لحن، مکث و زبان بدن","alborz":"جلسه چهارم: پیام سه‌مرحله‌ای، واژه‌گزینی، صدا، مکث، زبان بدن و هماهنگی کلام و رفتار","behparvar":"الزامات رفتار قابل مشاهده در مدل شایستگی و تصمیم‌های بین‌واحدی","outcome":"یک تصمیم حساس را در سه جمله، با لحن مناسب و امکان پرسش منتقل کند.","definition":"معنای پیام از کلمات، لحن و نشانه‌های غیرکلامی هم‌زمان ساخته می‌شود؛ تناقض میان آن‌ها اعتماد را کاهش می‌دهد.","tools":[["پیام مسئله–دلیل–اقدام","اصل تصمیم را در جمله اول بگو؛ یک دلیل لازم و یک اقدام بعدی اضافه کن.","«روش کنترل تغییر می‌کنه؛ به‌خاطر خطای تکرارشده؛ نمونه اجرای مجاز رو امروز مرور می‌کنیم.»"],["تنظیم صدا و مکث","جمله حساس را آهسته و روشن بگو؛ بعد از آن مکث واقعی کن تا پرسش بیاید.","«تغییر از شنبه اجرا می‌شه.» [مکث] «کدام مانع اجرا رو می‌بینید؟»"],["هماهنگی غیرکلامی","نگاه متعادل، بدن رو به مخاطب و چهره متناسب با موضوع را حفظ کن؛ اطمینان ظاهری نساز.","هنگام شنیدن نگرانی، تلفن را کنار بگذار و بدون لبخند نامناسب به مخاطب نگاه کن."]],"trap":"بلندتر گفتن پیام یا تکرار تصمیم به معنای فهم بیشتر مخاطب نیست.","transfer":"برای یک تغییر واقعی، متن سه‌جمله‌ای بنویس و از همکار بخواه اقدام بعدی را با زبان خودش بگوید.","decisionLens":"در ارزیابی گزینه‌ها تفاوت میان اعلام تصمیم، دریافت بازخورد و آزمون فهم واقعی را تشخیص بده.","debrief":["در کدام نوبت لحن یا مکث مسیر گفت‌وگو را تغییر داد؟","آیا دریافت‌کننده پیام توانست اقدام بعدی را با زبان خودش توضیح دهد؟"],"sup":{"case":"باید به گروهی از همکاران از واحدهای مختلف اعلام کنید که روش ثبت تحویل از هفته آینده تغییر می‌کند. برخی فکر می‌کنند کارشان بیشتر می‌شود و یک نفر می‌پرسد آیا با خطاهای روزهای اول برخورد انضباطی خواهد شد. اصل تغییر مصوب است، ولی نحوه حمایت و پرسش‌های اجرایی هنوز جای گفت‌وگو دارد.","roles":["سرپرست اعلام‌کننده تغییر","همکار نگران"],"roleBriefs":["نمی‌توانید اصل مصوبه را لغو کنید؛ باید ترس و ابهام اجرا را بدون وعده غیرمجاز مدیریت کنید.","با اصل کنترل مشکل ندارید، اما زمان کار و پیامد خطای اولیه برایتان مبهم است."],"dialogue":[["سرپرست","از شنبه شیوه ثبت تحویل تغییر می‌کنه؛ هدف کاهش خطاهای برگشتیه؛ امروز یک نمونه اجرا می‌کنیم."],["همکار","یعنی از هفته بعد زمان بیشتری صرف گزارش می‌شه؟"],["سرپرست","ممکنه در شروع کمی بیشتر وقت بگیره. [مکث] کدام بخشش برای اجرا مبهمه؟"],["همکار","اگر ورودی واحد دیگر دیر برسد، چه باید ثبت کنیم؟"],["سرپرست","طبق روش مصوب، وضعیت ورودی باز و مسئول پیگیری رو ثبت می‌کنیم؛ مورد مبهم رو برای تأیید به مسئول فرایند می‌فرستیم."],["همکار","پس اول ورودی باز رو مشخص می‌کنیم و بعد از طریق مسیر رسمی پیگیری می‌کنیم؟"]]},"mgr":{"case":"یک محدودیت موقت منابع برای مدیران اعلام می‌شود. مدیر مالی از فشار بودجه می‌گوید و مدیر فروش نگران وعده‌های مشتری است. شما اختیار اعلام استثنای قطعی ندارید ولی می‌توانید معیار درخواست استثنا و زمان پاسخ را توضیح دهید. جلسه با یک خبر ناخوشایند آغاز می‌شود.","roles":["مدیر ابلاغ‌کننده","مدیر معترض"],"roleBriefs":["تصمیم را روشن اعلام کنید و از توجیه طولانی بپرهیزید؛ مسیر استثنا را صرفاً در مرز اختیار بیان کنید.","نگران تعهد به مشتری هستید و می‌خواهید بدانید چه تصمیمی در اختیار خودتان باقی است."],"dialogue":[["مدیر ابلاغ‌کننده","برای یک ماه، هزینه‌های قابل تعویق محدود می‌شن؛ اولویت با تعهدهای ضروری و پرریسکه."],["مدیر معترض","ما قرارداد تحویل داریم؛ این تصمیم برای ما قابل اجرا نیست."],["مدیر ابلاغ‌کننده","اثر روی قرارداد رو درک می‌کنم. [مکث] کدام تعهد بدون استثنا دچار ریسک جدی می‌شه؟"],["مدیر معترض","پرداخت مرتبط با تأمین سفارش اصلی."],["مدیر ابلاغ‌کننده","پرونده استثنا رو با شواهد اثر و موعد، برای مرجع مجاز بررسی می‌فرستیم؛ فعلاً تأیید قطعی نمی‌دم."],["مدیر معترض","پس امروز درخواست مستند ثبت می‌کنیم و زمان پاسخ مشخص خواهد بود."]]}},{"skill":"بازخورد رفتاری، تفویض و توانمندسازی","alborz":"تکنیک‌های احترام به نقش تخصصی، گفت‌وگوی روشن و جمع‌بندی","behparvar":"نقشه مصوب جلسه ۴: بازخورد، تفویض اختیار، حمایت و پاسخ‌گویی (bp-curriculum-alignment-20261102.js)","outcome":"با شواهد رفتار گفت‌وگو کند و مسئولیت اصلاح را همراه با حمایت و اختیار واقعی به فرد بسپارد.","definition":"Feedback مؤثر رفتار را توصیف می‌کند؛ Empowerment اختیار تصمیم، منابع، حد ریسک و زمان بازبینی را هم روشن می‌سازد.","tools":[["شاهد–اثر–پرسش","یک رخداد مشخص و اثر آن را بگو؛ سپس مانع را بپرس، نه انگیزه را حدس بزن.","«دو گزارش بعد از موعد رسید؛ هماهنگی واحد بعدی عقب افتاد. چه مانعی بود؟»"],["تفویض همراه با مرز اختیار","نتیجه مورد انتظار، تصمیم‌های در اختیار فرد و موارد نیازمند تأیید را روشن کن.","«برنامه تکمیل با تو؛ تغییر تعهد مشتری باید با مرجع مجاز هماهنگ بشه.»"],["حمایت و بازبینی","منابع و کمک لازم را توافق کن و یک موعد سنجش رفتار تعیین کن.","«من هماهنگی ورودی رو انجام می‌دم؛ تو گزارش رو تکمیل کن؛ فردا نتیجه رو مرور می‌کنیم.»"]],"trap":"واگذاری کار بدون اختیار و پشتیبانی، تفویض نیست؛ انتقال فشار است.","transfer":"در بازخورد بعدی فقط «بهتر کار کن» نگو؛ تصمیم در اختیار فرد و حمایت خودت را هم مشخص کن.","decisionLens":"تفاوت بازخورد با سرزنش و تفاوت تفویض واقعی با واگذاری صرف کار را بررسی کن.","debrief":["آیا مدیر هم رفتار مورد انتظار را روشن کرد و هم اختیار واقعی را واگذار کرد؟","اگر مانع خارج از اختیار فرد بود، چه حمایت مشخصی پیشنهاد شد؟"],"sup":{"case":"یکی از کارشناسان گزارش مشترک را دو بار دیر تحویل داده ولی برای حل درخواست فوری واحد دیگر وقت گذاشته است. این بار موعد بعدی نزدیک است و یک ورودی از واحد دیگر هنوز نرسیده. لازم است بازخورد دهید، اما اگر فقط «منظم‌تر باش» بگویید، محدودیت فرایندی پابرجا می‌ماند.","roles":["سرپرست","کارشناس"],"roleBriefs":["به موعد تحویل متعهدید، اختیار هماهنگی بین‌واحدی دارید؛ نباید کل کار را شخصاً انجام دهید.","کمک به دیگران برایتان مهم است؛ نیاز دارید اولویت و مسیر خبرکردن مانع روشن باشد."],"dialogue":[["سرپرست","دو تحویل اخیر دیر شد و هماهنگی واحد بعدی عقب افتاد؛ در عین حال کمکت به آن واحد ارزشمند بود."],["کارشناس","ورودی‌ها دیر رسید و نخواستم کار آن‌ها معطل بشه."],["سرپرست","برای تحویل بعدی، کدام تصمیم رو می‌تونی خودت بگیری و کجا به حمایت من نیاز داری؟"],["کارشناس","می‌تونم پیش‌نویس رو به‌موقع ببندم؛ برای ورودی معوق نیاز به هماهنگی شما دارم."],["سرپرست","مسئولیت تکمیل با تو؛ پیگیری میان‌واحدی با من. اگر تا ساعت نه ورودی نرسید، وضعیت رو ثبت کن."],["کارشناس","پس فردا ساعت ده تحویل رو با معیار توافق‌شده مرور می‌کنیم."]]},"mgr":{"case":"مدیر یکی از واحدها شاخص‌های داخلی خود را محقق کرده، اما دو تعهد مشترک به واحدهای دیگر با تأخیر انجام شده است. او می‌گوید این تعهدها خارج از اولویت تیمش بوده‌اند. شما می‌خواهید Ownership او را تقویت کنید، نه اینکه خودتان تمام هماهنگی‌ها را بر عهده بگیرید.","roles":["مدیر راهبر","مدیر واحد"],"roleBriefs":["هدف ارتقای همکاری است، نه گرفتن اختیار مدیر واحد؛ مرز تصمیم و حمایت را شفاف کنید.","در برابر شاخص‌های خود پاسخ‌گو بوده‌اید اما تعهدهای مشترک در اولویت‌بندی‌تان مبهم بوده است."],"dialogue":[["مدیر راهبر","نتایج داخلی شما خوبه؛ اما دو تعهد مشترک دیر انجام شد و اثرش روی واحدهای دیگر مشخصه."],["مدیر واحد","تیم من ظرفیت محدودی داره و اولویت‌ها دائم عوض می‌شن."],["مدیر راهبر","برای هم‌راستایی، کدام تصمیم‌ها رو می‌تونی مستقیم بگیری و کدام تعارض اولویت نیاز به حمایت من داره؟"],["مدیر واحد","اولویت‌های داخل تیم با منه؛ تعارض با فروش و تأمین گاهی باید در سطح مدیران حل بشه."],["مدیر راهبر","پس هماهنگی رفع بن‌بست با من؛ تعهدها، مسئول‌ها و اطلاع‌رسانی به‌موقع با شما. دو هفته بعد شواهد رو مرور می‌کنیم."],["مدیر واحد","موافقم؛ معیار تأخیر و اطلاع‌رسانی رو هم مشترک ثبت می‌کنیم."]]}},{"skill":"جرأت‌ورزی، مرزبندی و مدیریت تعارض","alborz":"تکنیک ۲ پاسخ به انتقاد، تکنیک ۷ نه‌گفتن، تمرین گفت‌وگوی دشوار","behparvar":"کیس «کیفیت می‌گوید نه؛ تولید می‌گوید ناچاریم» و «اتهام شخصی» (behparvar-cases-4-6.js)","outcome":"در یک تعارض مشروع، شواهد، حدود اختیار و اقدام فوری مجاز را بدون حمله شخصی روشن کند.","definition":"Assertiveness یعنی بیان روشن موضع و مرز همراه با شنیدن منافع طرف دیگر؛ سازش بر سر استاندارد تخصصی مجاز نیست.","tools":[["مرزبندی با شاهد","به جای «واحد شما همکاری نمی‌کنه»، رخداد و ریسک را مشخص کن.","«تأیید کیفیت هنوز کامل نشده؛ نمی‌تونیم محموله رو تأییدشده اعلام کنیم.»"],["دو منفعت مشروع","فشار موعد و مرز تخصصی را هم‌زمان به رسمیت بشناس؛ یکی را با دیگری حذف نکن.","«تحویل فوری مهمه؛ تأیید فنی هم پیش‌شرط تصمیم مجازه.»"],["دو مسیر اقدام","اقدام فوری در اختیار و بررسی ریشه اختلاف را با دو مسئول جدا ببند.","«برای امروز برنامه جایگزین می‌سازیم؛ موعد پاسخ کیفیت رو از مسئول مجاز می‌گیریم.»"]],"trap":"توافقی که از مرز کیفیت، ایمنی یا صلاحیت تخصصی عبور کند، حل تعارض نیست.","transfer":"در اختلاف بعدی، «منافع مشترک» را جدا از «حد غیرقابل مصالحه» روی کاغذ بنویس.","decisionLens":"سؤال این نیست که کدام طرف کوتاه بیاید؛ سؤال این است که چه اقدام مجاز و قابل پیگیری می‌تواند ریسک هر دو طرف را کنترل کند.","debrief":["آیا تصمیمی خارج از اختیار تخصصی یک طرف اتخاذ شد؟","کدام جمله موضع قاطع را بدون تحقیر طرف مقابل حفظ کرد؟"],"sup":{"case":"سرپرست تولید می‌خواهد برنامه تحویل عقب نیفتد؛ سرپرست کیفیت می‌گوید بررسی یک محموله هنوز کامل نشده و اجازه اعلام «تأییدشده» ندارد. کارکنان منتظرند و فروش هم درباره موعد مشتری سؤال می‌کند. شما باید مسیر کار مجاز را پیدا کنید، بدون اینکه فشار زمان به تأیید غیرمجاز تبدیل شود.","roles":["سرپرست تولید","سرپرست کنترل کیفیت"],"roleBriefs":["فشار برنامه واقعی است؛ اختیار تغییر نتیجه بررسی کیفیت را ندارید.","داده تأیید کامل نیست؛ می‌توانید زمان بررسی و شواهد باقیمانده را روشن کنید، نه نتیجه نهایی را."],"dialogue":[["تولید","اگر همین‌جا متوقف بمونیم، تحویل امروز عقب می‌افته."],["کیفیت","هنوز شواهد تأیید کامل نیست؛ نمی‌تونم وضعیت رو آزاد اعلام کنم."],["تولید","متوجه محدودیتت هستم؛ چه زمانی می‌تونیم پاسخ معتبر داشته باشیم؟"],["کیفیت","نتیجه بررسی تکمیلی تا ساعت دو اعلام می‌شه؛ قطعی‌بودنش رو قول نمی‌دم."],["تولید","من برنامه جایگزین مجاز رو می‌چینم و وضعیت واقعی رو به ارسال اعلام می‌کنم."],["کیفیت","پس تأیید فنی با ما، برنامه جایگزین با شما؛ ساعت دو وضعیت رو مشترک مرور می‌کنیم."]]},"mgr":{"case":"مدیر عملیات و مدیر کیفیت درباره تحویل سفارش اختلاف دارند. نتیجه بررسی کیفیت هنوز قطعی نیست، تعهد مشتری مهم است و فروش خواسته عبارت «آماده ارسال» در پیام رسمی ثبت شود. تصمیم تجاری نمی‌تواند جای نتیجه تخصصی را بگیرد؛ مدیران باید درباره اطلاع‌رسانی درست و برنامه جایگزین توافق کنند.","roles":["مدیر عملیات","مدیر کیفیت"],"roleBriefs":["تعهد مشتری مهم است ولی نمی‌توانید تأیید کیفیت را جایگزین کنید.","باید زمان بررسی و حدود تصمیم خود را روشن کنید؛ از فشار تجاری آگاهید."],"dialogue":[["مدیر عملیات","فروش می‌گه امروز باید پیام «آماده ارسال» بدیم."],["مدیر کیفیت","تا بررسی نهایی، این عبارت دقیق نیست. وضعیت واقعی هنوز بازه."],["مدیر عملیات","با این مرز موافقم. برای تصمیم درباره برنامه جایگزین، چه داده و زمانی لازم داریم؟"],["مدیر کیفیت","شواهد یک آزمون باقی مونده؛ تا ساعت سه وضعیت معتبر رو اعلام می‌کنیم."],["مدیر عملیات","من با فروش درباره گزینه مرحله‌ای مشروط به تأیید صحبت می‌کنم؛ هیچ وعده قطعی نمی‌دیم."],["مدیر کیفیت","من هم معیار آزادسازی رو ثبت می‌کنم؛ تصمیم تجاری بعد از نتیجه معتبر انجام می‌شه."]]}},{"skill":"هماهنگی افقی و ساختن تعهد مشترک","alborz":"تکنیک ۹ شنیدن سه انتظار متفاوت و تکنیک ۱۰ جمع‌بندی","behparvar":"گفت‌وگوهای تولید/توزیع audience-content.js و نقشه BMCF نتایج مشترک","outcome":"یک بن‌بست ظرفیت میان واحدها را به درخواست دقیق، گزینه جایگزین و تعهد مشترک تبدیل کند.","definition":"Coordination با دستور یک‌طرفه شکل نمی‌گیرد؛ نیازمند شفافیت وابستگی، سنجش ظرفیت و ثبت تعهد دوطرفه است.","tools":[["درخواست قابل ارزیابی","خروجی، موعد، اهمیت و وابستگی را بگو؛ درخواست مبهم قابل برنامه‌ریزی نیست.","«برای برنامه تحویل، تا ساعت دو تأیید ظرفیت واقعی لازم داریم.»"],["گزینه‌سازی زیر محدودیت","اگر منابع ناکافی است، تحویل مرحله‌ای یا کاهش دامنه را با ریسک آن بررسی کن.","«برای سفارش اول خروجی قطعی و برای دوم زمان تازه پیشنهاد می‌دیم.»"],["تعهد متقابل","مسئول اقدام هر واحد و نقطه هشدار پیش از موعد را مشخص کن.","«تا دو تأمین پاسخ می‌ده؛ تا دو و ربع ارسال برنامه را بازبینی می‌کنه.»"]],"trap":"Escalation زودهنگام بدون مشخص‌کردن خروجی، ریسک و گزینه‌ها، اختلاف را فقط به سطح بالاتر منتقل می‌کند.","transfer":"در درخواست بین‌واحدی بعدی از الگوی «خروجی–موعد–وابستگی–مالک» استفاده کن.","decisionLens":"به گزینه‌ای دقت کن که هم استقلال دو واحد را حفظ کند، هم نیاز مشترک را با داده به تصمیم نزدیک کند.","debrief":["کدام سؤال محدودیت واقعی طرف مقابل را آشکار کرد؟","اگر موعد از دست برود، چه کسی چه زمانی هشدار می‌دهد؟"],"sup":{"case":"سرپرست تولید برای تکمیل برنامه امروز به یک ورودی از انبار نیاز دارد؛ انبار دو درخواست فوری دیگر هم دارد و ارسال برنامه را با موعد قبلی تنظیم کرده است. هیچ‌کس اختیار اضافه‌کردن نیروی تازه در لحظه را ندارد. با همکاری سرپرست انبار و ارسال باید حداقل خروجی لازم را تعیین کنید.","roles":["سرپرست تولید","سرپرست انبار"],"roleBriefs":["می‌خواهید برنامه تحویل را نجات دهید؛ برای اولویت‌دادن به همه درخواست‌ها اختیار ندارید.","ظرفیت محدود دارید؛ می‌توانید خروجی را مرحله‌ای آماده کنید."],"dialogue":[["تولید","برای برنامه امروز، به وضعیت این دو قلم تا ساعت دو نیاز داریم."],["انبار","تا دو همه‌اش نمی‌رسه؛ دو درخواست فوری دیگه هم داریم."],["تولید","کدوم بخش برای شروع کار قابل تحویله و باقی چه زمانی می‌رسه؟"],["انبار","موجودی قلم اول تا یک و نیم قطعی می‌شه؛ دوم رو باید سه اعلام کنیم."],["تولید","پس برنامه رو دو مرحله‌ای می‌چینیم و موعد جدید رو به ارسال می‌گیم."],["انبار","من مسئول اعلام اول و هشدار تأخیر دومم؛ ساعت دو وضعیت رو دوباره بررسی می‌کنیم."]]},"mgr":{"case":"مدیران تولید، توزیع و فروش برای یک سفارش مهم ظرفیت و موعد متفاوتی اعلام کرده‌اند. فروش روی موعد مشتری تأکید دارد؛ تولید برای تأمین ورودی‌ها زمان بیشتری می‌خواهد و توزیع ظرفیت حمل محدودی دارد. مدیر هماهنگ‌کننده باید تصمیم شرکتی بسازد، نه اینکه شاخص یک واحد را به همه تحمیل کند.","roles":["مدیر تولید","مدیر توزیع"],"roleBriefs":["می‌خواهید ظرفیت قابل دفاع را بگویید؛ نمی‌خواهید یک موعد غیرواقعی ثبت شود.","با ظرفیت حمل محدود و تعهد مشتری روبه‌رو هستید؛ می‌توانید تحویل مرحله‌ای بررسی کنید."],"dialogue":[["تولید","با این ورودی‌ها کل سفارش تا چهارشنبه آماده نمی‌شه."],["توزیع","مشتری برای بخش اول موعد قطعی می‌خواد و حمل چهارشنبه ظرفیت محدودی داره."],["تولید","چه حداقل مقدار برای تحویل اول واقعاً لازم و قابل حمله؟"],["توزیع","اگر بخش اول تا ظهر آماده باشه، می‌تونیم مسیر حمل رو تثبیت کنیم."],["تولید","پس ظرفیت تأییدشده رو تا امروز دو اعلام می‌کنم و برنامه دوم رو مشروط می‌گذاریم."],["توزیع","من هم ظرفیت حمل و نقطه هشدار رو ثبت می‌کنم؛ توافق رو با فروش مشترک نهایی می‌کنیم."]]}},{"skill":"نه‌گفتن حرفه‌ای و مدیریت انتظار ذی‌نفع","alborz":"تکنیک ۷ پاسخ قاطع و ۴ رعایت محدودیت محرمانگی در استقبال","behparvar":"تعهد میان‌واحدی، مرز اختیار و نیاز مشتری در مدل شایستگی به‌پرور","outcome":"با روشن‌کردن نیاز واقعی، محدودیت مشروع و گزینه جایگزین، درخواستی خارج از ظرفیت را مدیریت کند.","definition":"نه گفتن حرفه‌ای یعنی رد محترمانه تعهد ناممکن، همراه با توضیح معیار و حفظ مسیر همکاری.","tools":[["کشف ضرورت","پیش از رد یا قبول، اثر واقعی موعد را بپرس.","«اگر این کار امروز انجام نشه، کدام تعهد مشخص شما آسیب می‌بینه؟»"],["مرز بدون توجیه‌زدگی","دلیل روشن و مختصر بگو؛ قول استثنا خارج از اختیار نده.","«خارج از سقف تأییدشده نمی‌تونم تعهد بدهم.»"],["گزینه قابل اجرا","زمان، دامنه یا شیوه کار مجاز دیگری پیشنهاد کن و مالک پاسخ را ثبت کن.","«بخش ضروری تا چهار ممکنه؛ باقی طبق برنامه فردا بررسی می‌شه.»"]],"trap":"وعده موقتِ بدون تأیید برای آرام‌کردن ذی‌نفع، اعتبار رابطه را در مرحله اجرا تخریب می‌کند.","transfer":"درخواست خارج از ظرفیت بعدی را با «نیاز–مرز–گزینه–موعد پاسخ» مدیریت کن.","decisionLens":"گزینه‌ای بهتر است که مرز توان اجرا را حفظ کند ولی نیاز اصلی ذی‌نفع را بدون تحمیل حل‌ناشدنی رها نکند.","debrief":["در کدام جمله نیاز واقعی ذی‌نفع از درخواست ظاهری تفکیک شد؟","آیا گزینه جایگزین در حدود اختیار و ظرفیت واقعی بود؟"],"sup":{"case":"سرپرست یکی از واحدها از شما می‌خواهد یک گزارش مشترک را امروز خارج از نوبت تکمیل کنید. انجام کامل آن موجب تأخیر در تعهد قبلی به واحد دیگر می‌شود. درخواست‌کننده می‌گوید موعد مشتری‌اش نزدیک است، ولی هنوز مشخص نکرده دقیقاً کدام بخش گزارش لازم است.","roles":["سرپرست پاسخ‌گو","سرپرست درخواست‌کننده"],"roleBriefs":["امکان پذیرش کامل ندارید؛ شاید بخش ضروری در ظرفیت امروز بگنجد.","برای یک موعد فوری تحت فشارید؛ می‌توانید نیاز حداقلی را مشخص کنید."],"dialogue":[["درخواست‌کننده","می‌خوام این گزارش رو امروز کامل تحویل بدید."],["پاسخ‌گو","برای اینکه راه عملی پیدا کنیم، کدام بخش برای تعهد امروز ضروریه؟"],["درخواست‌کننده","فقط رقم‌های بخش اول باید تا عصر قطعی بشه."],["پاسخ‌گو","تکمیل کل گزارش امروز در ظرفیت ما نیست؛ بخش اول رو می‌تونیم تا چهار بررسی کنیم."],["درخواست‌کننده","پس با بخش دوم چیکار کنم؟"],["پاسخ‌گو","موعد بعدی رو با مسئول مشخص اعلام می‌کنیم تا تعهد جدیدی بدون ظرفیت نسازیم."]]},"mgr":{"case":"یک ذی‌نفع مهم می‌خواهد موعد اجرای پروژه یک هفته جلو بیفتد، اما منابع و تأیید لازم فراهم نیست. او تهدید می‌کند اگر موعد نرسد حمایت خود را پس می‌گیرد. مدیر پروژه نمی‌تواند کیفیت یا تعهدهای جاری را قربانی وعده‌ای کند که اختیار اجرای آن را ندارد.","roles":["مدیر پروژه","ذی‌نفع"],"roleBriefs":["برای رابطه بلندمدت ارزش قائلی اما مجاز به تعهد بدون منابع نیستید.","ریسک تأخیر برایتان واقعی است و می‌خواهید اقدام ملموس بشنوید."],"dialogue":[["ذی‌نفع","لازمه کل پروژه یک هفته زودتر آماده بشه."],["مدیر پروژه","متوجه فوریت هستم. دقیقاً کدام نتیجه باید در موعد جدید در دسترس باشه؟"],["ذی‌نفع","بخش مشتری‌محور؛ باقی رو می‌شه بعدتر آماده کرد."],["مدیر پروژه","تحویل کامل بدون منابع بیشتر قابل تعهد نیست؛ اما کاهش دامنه مرحله اول گزینه قابل بررسیه."],["ذی‌نفع","چه زمانی می‌تونید نتیجه قطعی بدید؟"],["مدیر پروژه","تا فردا سناریوها و ریسکشان رو برای تصمیم مرجع مجاز می‌فرستیم و زمان پاسخ رو اعلام می‌کنیم."]]}},{"skill":"رسیدگی به نارضایتی و بازیابی اعتماد","alborz":"تکنیک ۸ پاسخ به اعتراض و ۱ آغاز ارتباط با مخاطب ناراضی","behparvar":"سناریوهای کیفیت، تحویل و پاسخ‌گویی مشتری در پرونده‌های اصلی شرکت","outcome":"شکایت را به اثر واقعی، تعهد پیگیری و اصلاح قابل ارزیابی تبدیل کند.","definition":"بازسازی اعتماد فقط عذرخواهی نیست؛ شنیدن اثر مشکل، شفافیت درباره وضعیت و تکرار پاسخ‌گویی در موعد توافق‌شده است.","tools":[["بازتاب اثر","قبل از توضیح علت، هزینه یا پیامد مشکل برای مخاطب را بپرس.","«این تأخیر برای برنامه مشتری شما چه پیامدی داشت؟»"],["تفکیک وضعیت از نتیجه","آنچه می‌دانید، آنچه نیازمند بررسی است و مسئول پاسخ را جدا کنید.","«علت هنوز در بررسیه؛ تا دو وضعیت معتبر رو اعلام می‌کنم، نه نتیجه قطعی رو.»"],["بستن حلقه پیگیری","حتی بدون حل نهایی، در زمان مقرر وضعیت و قدم بعدی را خبر بده.","«اگر حل نشده باشه هم وضعیت واقعی و زمان بررسی بعد رو اطلاع می‌دم.»"]],"trap":"ارجاع موضوع به واحد تخصصی بدون مالک پاسخ‌گویی، از دید مخاطب رهاکردن شکایت است.","transfer":"برای یکی از درخواست‌های معوق، قبل از موعد نتیجه، یک زمان اطلاع‌رسانی معتبر تعیین کن.","decisionLens":"تفکیک کن: پذیرش اثر مشکل، پذیرش تقصیر، اعلام نتیجه و تعهد اطلاع‌رسانی چهار عمل متفاوت‌اند.","debrief":["آیا مسئول پاسخ‌گویی تا زمان رفع مشکل مشخص ماند؟","کدام وعده در اختیار مدیر بود و کدام ادعا نیازمند بررسی تخصصی؟"],"sup":{"case":"واحد توزیع از سه پاسخ متفاوت درباره آماده‌بودن یک سفارش ناراضی است؛ مشتری نهایی هم برنامه تحویل خود را بر اساس این پاسخ‌ها تغییر داده است. وضعیت فنی هنوز نزد مسئول بررسی باز است. سرپرست باید از رنج انتظار بکاهد، بدون اعلام آمادگی غیرمجاز.","roles":["سرپرست پاسخ‌گو","همکار واحد توزیع"],"roleBriefs":["نتیجه بررسی فنی در اختیار شما نیست؛ تعهد پاسخ‌گویی و پیگیری در اختیار شماست.","پاسخ‌های متناقض باعث آسیب به اعتبار شما نزد مشتری شده است."],"dialogue":[["توزیع","سه بار پرسیدیم و هر بار زمان متفاوت گفتید؛ مشتری دیگه به ما اعتماد نمی‌کنه."],["سرپرست","درک می‌کنم این اختلاف پاسخ چه اثری روی برنامه شما گذاشته. مهم‌ترین موعدی که آسیب دیده کدومه؟"],["توزیع","برنامه ارسال امروز؛ من به یک وضعیت قابل اتکا نیاز دارم."],["سرپرست","تا ساعت دو وضعیت معتبر رو از صاحب اختیار می‌گیرم؛ قبل از اون آماده‌بودن رو قطعی اعلام نمی‌کنم."],["توزیع","اگر تا دو هم نتیجه نبود چی؟"],["سرپرست","همان ساعت وضعیت واقعی و قدم بعدی رو اطلاع می‌دم؛ پیگیری با منه."]]},"mgr":{"case":"نماینده یک مشتری سازمانی از تکرار مسئله کیفیت و گزارش‌های متناقض سه واحد ناراضی است و ادامه همکاری را زیر سؤال برده است. مدیر مربوطه باید موضوع را با شواهد بررسی کند؛ جبران یا تضمین عدم تکرار بدون تأیید مرجع مجاز ممکن نیست.","roles":["مدیر پاسخ‌گو","نماینده مشتری"],"roleBriefs":["فوریت حفظ اعتماد بالاست؛ هنوز نتیجه ریشه‌یابی و اختیار جبران روشن نیست.","آسیب به اعتبارتان نزد مشتری نهایی جدی است و از وعده‌های مبهم خسته‌اید."],"dialogue":[["مشتری","این مشکل تکرار شده؛ چطور به وعده تحویل بعدی اعتماد کنیم؟"],["مدیر","اثر تکرار روی برنامه شما رو جدی می‌گیرم. بیشترین پیامد برای کدام تعهد بوده؟"],["مشتری","در برابر مشتری خودمون پاسخ‌گو نیستیم چون زمان‌های متفاوت می‌شنویم."],["مدیر","مالک ارتباط منم؛ نتیجه بررسی فنی رو از مرجع مسئول می‌گیرم و یک زمان معتبر برای گزارش اعلام می‌کنم."],["مشتری","من به تضمین نیاز دارم نه یک گزارش دیگه."],["مدیر","قول غیرقابل تأیید نمی‌دم؛ معیار کنترل و زمان مرور اقدام اصلاحی رو به‌طور شفاف با شما توافق می‌کنیم."]]}},{"skill":"اقناع مبتنی بر منافع و جمع‌بندی دیجیتال","alborz":"تکنیک ۱۰ جمع‌بندی نهایی + جلسه چهارم پیام روشن؛ رعایت محرمانگی در ارتباط رسمی","behparvar":"هدف جلسه ۴: توافق، تفویض مالکیت و پیگیری؛ audience-content.js و bp-curriculum-alignment-20261102.js","outcome":"یک مذاکره بین‌واحدی را با گزینه‌های قابل دفاع به توافق برساند و آن را در پیام دیجیتال امن و قابل پیگیری ثبت کند.","definition":"اقناع حرفه‌ای بر فهم منافع و شواهد استوار است؛ گفت‌وگو تنها وقتی به نتیجه می‌رسد که تعهد کوتاه، شفاف و قابل ردیابی ثبت شود.","tools":[["پرسش از معیار تصمیم","پیش از پیشنهاد، بپرس طرف مقابل بر اساس کدام ریسک یا منفعت تصمیم می‌گیرد.","«برای تخصیص ظرفیت، کدام تعهد جاری نباید آسیب ببینه؟»"],["گزینه‌سازی و آزمون پیامد","دو گزینه واقعی همراه پیامد زمان، ظرفیت و ریسک مطرح کن؛ از فشار حیثیتی پرهیز کن.","«گزینه اول شروع محدود این هفته است؛ گزینه دوم موعد دیرتر با دامنه کامل.»"],["پیام دیجیتال پنج‌جزئی","در کانال مجاز، موضوع، توافق، مسئول هر اقدام، موعد و شرط بازبینی را کوتاه بنویس؛ محرمانگی را رعایت کن.","«موضوع: برنامه مشترک؛ تولید: بخش اول تا دوشنبه؛ توزیع: ظرفیت تا سه‌شنبه؛ بازبینی: چهارشنبه؛ داده محرمانه پیوست نشود.»"]],"trap":"ارسال «همه توافق کردیم» در گروه، جای ثبت دقیق مسئول، موعد و حدود اطلاعات مجاز را نمی‌گیرد.","transfer":"پس از گفت‌وگوی بعدی، یک پیام پنج‌جزئی در کانال مجاز ارسال کن و برداشت دریافت‌کننده را تأیید بگیر.","decisionLens":"موفقیت مذاکره را با تعداد موافقت‌ها نسنج؛ قابلیت اجرا، اختیار تصمیم، وضوح پیام و بازبینی را ملاک بگذار.","debrief":["کدام سؤال منافع واقعی را به‌جای مواضع اولیه روشن کرد؟","آیا پیام جمع‌بندی مسئول، موعد، مرز محرمانگی و شرط بازنگری داشت؟"],"sup":{"case":"سرپرست تولید و سرپرست توزیع بر سر جابه‌جایی زمان تحویل اختلاف دارند. تولید می‌تواند بخشی از سفارش را زودتر آماده کند، ولی توزیع برای حمل کامل ظرفیت ندارد. پس از توافق شفاهی باید در کانال رسمی شرکت خلاصه‌ای ثبت شود؛ درج اطلاعات مشتری خارج از کانال مجاز ممنوع است.","roles":["سرپرست تولید","سرپرست توزیع"],"roleBriefs":["فشار برنامه دارید و قادر به تحویل مرحله‌ای هستید؛ موعد بدون تأیید ظرفیت حمل نسازید.","ظرفیت حمل محدوده؛ آمادگی همکاری دارید اگر دامنه و زمان دقیق باشد."],"dialogue":[["تولید","برای تحویل این هفته به تغییر زمان نیاز داریم؛ کدام محدودیت شما جدی‌تره؟"],["توزیع","ظرفیت حمل دوشنبه کمه؛ ولی برای بخش اول امکان داره."],["تولید","اگر بخش اول رو دوشنبه آماده کنیم و بخش دوم رو چهارشنبه، ریسک برنامه شما چقدره؟"],["توزیع","با تأیید مقدار و زمان از امروز، می‌تونیم حمل اول رو برنامه‌ریزی کنیم."],["تولید","پس توافق رو با مسئول و موعد در کانال مجاز ثبت می‌کنم؛ اطلاعات محرمانه سفارش رو وارد گروه عمومی نمی‌کنیم."],["توزیع","من هم ظرفیت و زمان بازبینی رو تأیید می‌کنم؛ اگر مانع تازه بود پیش از موعد هشدار می‌دم."]]},"mgr":{"case":"برای یک طرح توسعه میان مدیران تولید، مالی و فروش، منابع کافی برای اجرای کامل یک‌باره وجود ندارد. یکی از مدیران فقط روی موعد مشتری و دیگری بر حفظ نقدینگی تأکید می‌کند. قرار است درباره اجرای محدود یا فازبندی توافق کنند و نتیجه را در صورت‌جلسه دیجیتالِ دارای دسترسی مناسب ثبت کنند.","roles":["مدیر توسعه","مدیر مالی"],"roleBriefs":["بر اساس ارزش و ریسک کل شرکت تصمیم مشترک می‌خواهید؛ منابع دیگران را یک‌طرفه تخصیص ندهید.","با محدودیت نقدینگی روبه‌رو هستید؛ اجرای آزمایشی در صورت کنترل ریسک برایتان قابل بررسی است."],"dialogue":[["مدیر توسعه","برای تصمیم مشترک، کدام محدودیت مالی نباید در این طرح نقض بشه؟"],["مدیر مالی","تعهدهای نقدی فعلی؛ بدون نقطه توقف نمی‌تونیم همه منابع رو تخصیص بدیم."],["مدیر توسعه","پس دو گزینه داریم: اجرای محدود با سنجه مشخص یا موعد دیرتر برای دامنه کامل."],["مدیر مالی","اجرای محدود، اگر سقف هزینه و زمان مرور داشته باشه، قابل دفاع‌تره."],["مدیر توسعه","مسئول فاز اول، سقف مجاز و معیار بازبینی رو در صورت‌جلسه دیجیتال ثبت می‌کنم."],["مدیر مالی","بعد از بررسی در مرجع تصمیم‌گیر، نسخه تأییدشده رو از کانال مجاز برای واحدها می‌فرستیم."]]}}]};
